// Asserts that two process queues have identical process data (ID, AT, BT, priority, CT, WT, TAT) in the same order.
void assert_process_queue_equal(struct node *actual, struct node *expected) {
    struct node *actual_ptr = actual;
    struct node *expected_ptr = expected;
    while (actual_ptr != NULL && expected_ptr != NULL) {
        TEST_ASSERT_EQUAL(expected_ptr->ID, actual_ptr->ID);
        TEST_ASSERT_EQUAL(expected_ptr->AT, actual_ptr->AT);
        TEST_ASSERT_EQUAL(expected_ptr->BT, actual_ptr->BT);
        TEST_ASSERT_EQUAL(expected_ptr->priority, actual_ptr->priority);
        TEST_ASSERT_EQUAL(expected_ptr->CT, actual_ptr->CT);
        TEST_ASSERT_EQUAL(expected_ptr->WT, actual_ptr->WT);
        TEST_ASSERT_EQUAL(expected_ptr->TAT, actual_ptr->TAT);
        actual_ptr = actual_ptr->next;
        expected_ptr = expected_ptr->next;
    }
    TEST_ASSERT_NULL(actual_ptr);
    TEST_ASSERT_NULL(expected_ptr);
}

// Asserts that the average CT, TAT, and WT calculated for a process queue match expected values within a small tolerance.
void assert_process_times_correct(struct node **root, float expected_avgCT, float expected_avgTAT, float expected_avgWT) {
    float tolerance = 0.001f;
    float actual_avgCT = 0.0f;
    float actual_avgTAT = 0.0f;
    float actual_avgWT = 0.0f;
    // Calculate actual averages
    struct node *ptr = *root;
    int count = 0;
    while (ptr != NULL) {
        actual_avgCT += ptr->CT;
        actual_avgTAT += ptr->TAT;
        actual_avgWT += ptr->WT;
        count++;
        ptr = ptr->next;
    }
    if (count > 0) {
        actual_avgCT /= count;
        actual_avgTAT /= count;
        actual_avgWT /= count;
    }
    TEST_ASSERT_FLOAT_WITHIN(tolerance, expected_avgCT, actual_avgCT);
    TEST_ASSERT_FLOAT_WITHIN(tolerance, expected_avgTAT, actual_avgTAT);
    TEST_ASSERT_FLOAT_WITHIN(tolerance, expected_avgWT, actual_avgWT);
}

